const input=$json.body??$json;
const arr=v=>Array.isArray(v)?v:[];
const truthy=v=>v===true||v==="true"||v===1||v==="1";
const milestones=arr(input.milestones);
const blockers=arr(input.blockers);
const identityComplete=Boolean(input.deal_id&&input.lead_id&&input.property_id);
const execution=input.execution??{};
const active=truthy(input.closing_active)||truthy(execution.active)||["active","in_progress","closing_active"].includes(String(execution.status||"").toLowerCase());
const closingDate=input.closing_date?new Date(input.closing_date):null;
const closingDateValid=Boolean(input.closing_date)&&!Number.isNaN(closingDate?.getTime());
const now=new Date();
const daysRemaining=closingDateValid?Math.ceil((closingDate-now)/86400000):null;
const overdue=milestones.filter(m=>truthy(m.overdue)||["overdue","failed"].includes(String(m.status||"").toLowerCase()));
const criticalOverdue=overdue.filter(m=>truthy(m.critical)||String(m.priority||"").toLowerCase()==="critical");
const incomplete=milestones.filter(m=>!truthy(m.completed)&&!["completed","done","verified"].includes(String(m.status||"").toLowerCase()));
const completed=milestones.length>0&&incomplete.length===0;
const closingDueSoon=closingDateValid&&daysRemaining>=0&&daysRemaining<=3;
const blockersClear=blockers.length===0;

let status="milestone_update_required",nextWorkflow="WF-280",humanReview=false;
if(!identityComplete){status="blocked_missing_identity";nextWorkflow="WF-126";humanReview=true;}
else if(!active){status="closing_not_active";nextWorkflow="WF-279";humanReview=true;}
else if(!closingDateValid||!blockersClear){status="blocked";nextWorkflow="WF-126";humanReview=true;}
else if(criticalOverdue.length>0){status="critical_overdue";nextWorkflow="WF-281";humanReview=true;}
else if(overdue.length>0){status="overdue";nextWorkflow="WF-281";humanReview=true;}
else if(completed){status="milestones_completed";nextWorkflow="WF-281";}
else if(closingDueSoon){status="closing_due_soon";nextWorkflow="WF-281";}
else{status="on_track";nextWorkflow="WF-280";}

return [{json:{...input,workflow:"WF-280",workflow_name:"Active Closing Milestone Orchestrator → Milestone Update & Critical-Date Controller",status,critical_date_monitor:{identity_complete:identityComplete,closing_active:active,closing_date_valid:closingDateValid,days_remaining:daysRemaining,closing_due_soon:closingDueSoon,blockers_clear:blockersClear,milestone_count:milestones.length,incomplete_count:incomplete.length,overdue_count:overdue.length,critical_overdue_count:criticalOverdue.length,completed},next_workflow:nextWorkflow,human_review_required:humanReview,routing_reason:status,audit:{event_type:"closing_milestone_update_critical_date_monitor",idempotency_key:input.idempotency_key||`wf-280:${input.deal_id||"unknown"}:${input.milestone_update_id||"none"}:${input.version||1}`}}}];
